mon_story=[re.sub(r'\s+',' ',p).strip() for p in re.findall(r'<p>(.*?)</p>', mon_html[mon_html.index('class="story"'):mon_html.index('What Luther discovered')],re.S)]
DAYS=[
dict(day="Mon",date="Oct 19",title="The Door to Paradise",reader="8th grader",
 ref="Ephesians 2:8–9",verses=[(8,"For by grace you have been saved through faith. And this is not your own doing; it is the gift of God,"),(9,"not a result of works, so that no one may boast.")],
 story_title="Martin Luther and the thunderstorm",story=mon_story,
 teach=["Lutherans sum it up in three short phrases: <b>grace alone</b> (God saves us as a free gift), <b>faith alone</b> (we receive it by trusting Jesus), and <b>Scripture alone</b> (God’s Word tells us so). That’s exactly what Ephesians 2:8–9 says.","We still try to obey God, but not to earn His love. We obey because we already have it."],
 teach_title="What Luther discovered",
 q=[("K and 1st","What scared Martin in the storm? Do we have to earn God’s love, or is it a gift?"),("3rd and 5th","Why couldn’t Martin feel good enough, no matter how hard he tried? What changed when he read Romans 1:17?"),("8th","Lots of people still think they have to be “good enough” for God. Why is grace such good news? If we’re saved by grace, why do we still try to do good?")],
 prayer="Heavenly Father, thank You for opening Martin Luther’s eyes to the good news, and for giving us that same gift. Thank You that we don’t have to earn Your love, because Jesus earned it for us.",
 ask="When we feel like we’re not good enough, remind us that we are Yours by grace.",
 bless="You are baptized. God’s love is a gift, not a grade.",
 kids=dict(lede="Martin Luther tried so hard to be good enough for God. Then he read the Bible and learned that God’s love is a free gift because of Jesus!",
  blanks=["Martin was caught in a big ___.","He promised to become a ___.","He read God’s Word, the ___.","God’s love is a free ___!","___ died on the cross for us."],bank=["gift","monk","storm","Jesus","Bible"],
  words=["GIFT","GRACE","FAITH","BIBLE","JESUS","LUTHER","STORM"],
  quiz=[("Do we earn God’s love by being good?",["Yes","No"]),("God’s love is a…",["Gift","Paycheck"])],
  draw="Draw a present. Inside, draw something God gives you for free.",mv=("Ephesians 2:8","“By grace you have been saved through faith.”"))),
dict(day="Tue",date="Oct 20",title="The Hammer and the Door",reader="3rd grader",
 ref="Romans 3:23–24",verses=[(23,"for all have sinned and fall short of the glory of God,"),(24,"and are justified by his grace as a gift, through the redemption that is in Christ Jesus,")],
 story_title="The 95 Theses",story=[
 "Remember how Martin Luther discovered that God’s forgiveness is a free gift? Well, not everyone was teaching that. In those days, the church needed money to build a giant new church in Rome called St. Peter’s. So church leaders began selling pieces of paper called <i>indulgences</i>. People were told that if they paid money, their sins, or the sins of a loved one who had died, would be forgiven.",
 "A preacher named Johann Tetzel traveled from town to town selling them. He even had a catchy rhyme: “As soon as the coin in the box rings, the soul from purgatory springs!” Poor families gave money they couldn’t spare, hoping to buy God’s forgiveness. Some people in Luther’s own church came to confession waving their papers and said, “I don’t need to be sorry. I already paid.”",
 "Luther was heartbroken and angry. He knew forgiveness can’t be bought. Jesus already paid for it with His own blood on the cross, and He gives it away for free. So Luther sat down and wrote ninety-five statements, called theses, explaining what was wrong with selling forgiveness. One of them said: “The true treasure of the church is the most holy gospel of the glory and grace of God.”",
 "On October 31, 1517, the day before All Saints’ Day, Luther walked up to the big wooden door of the Castle Church in Wittenberg and nailed up his 95 Theses. Back then, the church door was like a town bulletin board. Luther only wanted the teachers and priests to discuss it. But people copied his words, translated them into German, and printed them on the brand-new printing press. In just a few weeks, people all over Germany were reading them.",
 "Luther had no idea what he was starting. That’s why Lutherans celebrate October 31 as Reformation Day, the day the church began to be “re-formed” around the good news of Jesus."],
 teach_title="Forgiveness is free",
 teach=["Romans 3:24 says we are justified “by his grace as a gift.” A gift you pay for isn’t a gift anymore. Jesus paid the whole price, so we receive forgiveness with empty hands.","That’s why we hear the words of absolution at church: “I forgive you all your sins.” It costs us nothing because it cost Jesus everything."],
 q=[("K and 1st","What did Luther nail to the church door? Can we buy God’s forgiveness with money?"),("3rd and 5th","Why was Luther so upset about indulgences? Why do you think his 95 Theses spread so fast?"),("8th","What’s the difference between a gift and a payment? Where do people today still try to “pay” God back or earn His approval?")],
 prayer="Lord Jesus, thank You for paying for all our sins on the cross, so that forgiveness is a free gift. Thank You for brave people like Martin Luther who told the truth about Your grace.",
 ask="Help us remember that we can’t earn Your love and don’t have to.",
 bless="You are baptized. Jesus already paid for you.",
 kids=dict(lede="Luther nailed 95 Theses to the church door to teach that God’s forgiveness can’t be bought. Jesus paid for it!",
  blanks=["People were told to buy papers called ___.","Luther wrote ___ theses.","He nailed them to the church ___.","It was October 31, ___.","Forgiveness is a free gift from ___."],bank=["95","Jesus","1517","door","indulgences"],
  words=["DOOR","HAMMER","GRACE","FREE","GIFT","CHURCH","TRUTH"],
  quiz=[("Can money buy God’s forgiveness?",["Yes","No"]),("Who paid for our sins?",["Jesus","Tetzel"])],
  draw="Draw your own church door with a note that tells good news about Jesus.",mv=("Romans 3:24","“Justified by his grace as a gift.”"))),
dict(day="Wed",date="Oct 21",title="Here I Stand",reader="5th grader",
 ref="Psalm 46:1–3, 7",verses=[(1,"God is our refuge and strength, a very present help in trouble."),(2,"Therefore we will not fear though the earth gives way, though the mountains be moved into the heart of the sea,"),(3,"though its waters roar and foam, though the mountains tremble at its swelling. Selah"),(7,"The LORD of hosts is with us; the God of Jacob is our fortress. Selah")],
 story_title="Luther before the emperor",story=[
 "After the 95 Theses, Luther kept writing books about the good news of Jesus. The pope and the church leaders were furious. They ordered Luther to take back everything he had written. Luther refused, so in 1521 he was called to a city named Worms to stand trial before the most powerful man in Europe, Emperor Charles V.",
 "Luther’s friends were afraid. Years earlier, another preacher named Jan Hus had been promised safety at a trial like this, and he was burned at the stake anyway. But Luther said he would go even if there were as many devils in Worms as tiles on the roofs.",
 "Luther walked into a great hall packed with princes, bishops, and soldiers. On a table sat a big pile of his books. An official pointed to them and asked two questions: “Did you write these books? And will you take back what is in them?” Luther said yes, they were his. Then, surprising everyone, he asked for a day to think and pray. That night, Luther prayed hard, asking God for courage.",
 "The next day, the hall was even more crowded. Luther stood before the emperor and said: “Unless I am convinced by Scripture and plain reason, I cannot and will not take anything back. My conscience is captive to the Word of God. Here I stand. I can do no other. God help me. Amen.”",
 "Luther was declared an outlaw. Anyone could capture him, or even kill him, without punishment. Luther left Worms not knowing what would happen to him. But he knew Who was with him. Years later he wrote a hymn based on tonight’s psalm: “A Mighty Fortress Is Our God.”"],
 teach_title="Standing on God’s Word",
 teach=["Luther wasn’t brave because he was strong. He was brave because he trusted God’s Word more than any king. Psalm 46 says God is our refuge and fortress, a safe place to run when things are scary.","You won’t stand before an emperor, but you will have moments when standing for Jesus is hard. God is your fortress then too."],
 q=[("K and 1st","Who did Luther stand in front of? Who helped Luther be brave?"),("3rd and 5th","Why did Luther ask for one more day before he answered? What do you do when you need courage?"),("8th","Luther said his conscience was “captive to the Word of God.” What does that mean? When might standing on God’s Word cost you something?")],
 prayer="Mighty God, You are our refuge and strength. Thank You for giving Martin Luther courage to stand on Your Word, even when it was dangerous.",
 ask="When we are afraid, be our fortress, and help us stand for You.",
 bless="You are baptized. God is your mighty fortress.",
 kids=dict(lede="Luther stood before the emperor and would not take back the truth about Jesus. God gave him courage!",
  blanks=["Luther stood before the ___.","A big pile of his ___ was on the table.","Luther asked for one day to ___.","He said, “Here I ___.”","God is our mighty ___."],bank=["books","pray","stand","fortress","emperor"],
  words=["STAND","BRAVE","EMPEROR","FORTRESS","WORD","PRAY","WORMS"],
  quiz=[("Did Luther take back what he wrote?",["Yes","No"]),("Where do we get courage?",["From God","From being strong"])],
  draw="Draw a strong castle, and write a word inside that tells what God is like.",mv=("Psalm 46:1","“God is our refuge and strength, a very present help in trouble.”"))),
dict(day="Thu",date="Oct 22",title="The Knight in the Castle",reader="8th grader",
 ref="Psalm 119:105; 2 Timothy 3:16–17",verses=[("Ps 119:105","Your word is a lamp to my feet and a light to my path."),("2 Tim 3:16","All Scripture is breathed out by God and profitable for teaching, for reproof, for correction, and for training in righteousness,"),("17","that the man of God may be complete, equipped for every good work.")],
 story_title="Kidnapped!",story=[
 "Remember, Luther left Worms as an outlaw. As he rode home through a dark forest, a band of masked horsemen burst out of the trees. They grabbed Luther, threw him on a horse, and galloped away. News spread that Luther had been kidnapped, maybe even killed.",
 "But it was a rescue! The horsemen were sent by Luther’s friend, Prince Frederick the Wise, to hide him where no one could find him. They took him to Wartburg Castle, high on a hill. To keep his secret, Luther grew a beard, wore a knight’s clothes, and went by a new name: Knight George.",
 "Luther could have just waited it out. Instead, he got to work on something he had dreamed about for a long time. In those days, the Bible was mostly in Latin, a language ordinary people couldn’t read. Luther wanted every farmer, mother, and child in Germany to be able to read God’s Word for themselves.",
 "So, alone in a small room by candlelight, Luther translated the whole New Testament from Greek into German. It took him only about eleven weeks! When it was printed, thousands of copies sold right away, and families read the Bible together at home in their own language for the first time. (There’s an old legend that Luther once threw his inkwell at the devil in that room. Nobody knows if it’s true, but people still show visitors an ink spot on the wall!)",
 "The Bible you have on your shelf, in English, is there because people like Luther and other translators worked hard so that everyone could hear God speak in their own words."],
 teach_title="A lamp for our feet",
 teach=["God’s Word is like a lamp in a dark forest. It doesn’t show us everything at once, but it lights up the next step.","2 Timothy says all Scripture is “breathed out by God.” When we read the Bible, God Himself is speaking to us. That’s why Luther thought every family needed one."],
 q=[("K and 1st","Where did Luther hide? What did he write in the castle?"),("3rd and 5th","Why couldn’t most people read the Bible before Luther? Why did Luther want families to read it at home?"),("8th","What would change if you could never read the Bible yourself? How is God’s Word a lamp for the decisions you face?")],
 prayer="Heavenly Father, thank You for Your Word, our lamp and light. Thank You for keeping Martin Luther safe, and for giving people the Bible in their own language.",
 ask="Help us love Your Word and read it together.",
 bless="You are baptized. God’s Word lights your path.",
 kids=dict(lede="Luther hid in Wartburg Castle as “Knight George” and translated the New Testament so families could read God’s Word!",
  blanks=["Masked riders took Luther to a ___.","He pretended to be Knight ___.","He grew a ___.","He put the Bible into the German ___.","God’s Word is a ___ to my feet."],bank=["lamp","beard","George","language","castle"],
  words=["CASTLE","KNIGHT","BIBLE","LAMP","LIGHT","GERMAN","WORD"],
  quiz=[("Was Luther really kidnapped by enemies?",["Yes","No, by friends"]),("God’s Word is like a…",["Lamp","Locked box"])],
  draw="Draw your family’s Bible and something you love about it.",mv=("Psalm 119:105","“Your word is a lamp to my feet and a light to my path.”"))),
dict(day="Fri",date="Oct 23",title="A Book for Every Family",reader="Mom or Dad, with everyone saying verse 7",
 ref="Deuteronomy 6:4–7",verses=[(4,"“Hear, O Israel: The LORD our God, the LORD is one."),(5,"You shall love the LORD your God with all your heart and with all your soul and with all your might."),(6,"And these words that I command you today shall be on your heart."),(7,"You shall teach them diligently to your children, and shall talk of them when you sit in your house, and when you walk by the way, and when you lie down, and when you rise.")],
 story_title="Luther’s family and the Small Catechism",story=[
 "When Luther came out of hiding, the Reformation was spreading everywhere. Some nuns who had read his writings wanted to leave their convent and serve God in ordinary life. Leaving was dangerous, so a friend of Luther’s smuggled twelve of them out in his wagon, hidden among barrels of fish!",
 "One of those nuns was a strong, smart woman named Katharina von Bora. In 1525, she and Martin Luther got married. Their home in Wittenberg became noisy and full: six children, students, guests, and friends crowded around the dinner table. Katie ran the house, the farm, and even a brewery. Luther called her “my lord Katie.”",
 "A few years later, Luther traveled around visiting churches, and he was shocked. Many people, and even some pastors, didn’t know the Lord’s Prayer, the Ten Commandments, or the Creed. Luther thought, “Who will teach the children?” And he decided the answer was: their parents.",
 "So in 1529 Luther wrote the Small Catechism. It’s short and simple, with the Ten Commandments, the Creed, the Lord’s Prayer, Baptism, Confession, and the Lord’s Supper, each with the question, “What does this mean?” At the top of each part he wrote that it was for “the head of the family” to teach “to his household.” It was made for families to use at home, around the table.",
 "Luther himself said that even as an old doctor of the church, he still prayed the catechism every day, like a child. Five hundred years later, families all over the world still use it. In fact, that’s exactly what our family is doing every night."],
 teach_title="Faith at the dinner table",
 teach=["Deuteronomy 6 says to talk about God’s Word “when you sit in your house.” Luther believed the most important church lessons happen at home, not just at church or school.","Every night we gather, read God’s Word, and pray, we’re doing exactly what God asked and what Luther hoped families would do."],
 q=[("K and 1st","How did Katie escape the convent? Who did Luther write the Small Catechism for?"),("3rd and 5th","What surprised Luther when he visited churches? Why do you think he wanted parents to be the teachers?"),("8th","Why might faith learned at home stick better than faith learned only at church or school? What part of the catechism do you know best?")],
 prayer="Heavenly Father, thank You for Martin and Katie Luther and their family, and for the Small Catechism that still teaches families today. Thank You for our family and for our time together every night.",
 ask="Write Your Word on our hearts, and keep our family close to You.",
 bless="You are baptized. You belong to God, and to this family.",
 kids=dict(lede="Martin and Katie Luther had a big, busy family. Luther wrote the Small Catechism so families could learn about God at home!",
  blanks=["Katie escaped hidden among ___ barrels.","Martin and Katie had ___ children.","Luther wrote the Small ___.","It asks, “What does this ___?”","God’s Word is for our ___, too!"],bank=["six","mean","family","fish","Catechism"],
  words=["FAMILY","KATIE","HOME","PRAY","TABLE","CREED","LOVE"],
  quiz=[("Who should teach kids about God?",["Only pastors","Moms and dads too"]),("The Small Catechism was written for…",["Families","Only scholars"])],
  draw="Draw our family at the table during devotions.",mv=("Deuteronomy 6:7","“You shall teach them diligently to your children.”"))),
]
